model.component("comp1").physics("ftg").create("vibr1", "VibrationFatigueModel", 2);
// Frequency history: Logarithmic frequency sweep, C_l = 1 octave/min
// Application Library: Fatigue_Module/Harmonic_Vibration/bracket_fatigue_harmonic_vibration

model.component("comp1").physics().create("srotf", "SolidRotorFixedFrame", "geom1");
model.component("comp1").physics("srotf").create("jrb1", "JournalBearing", 2);
// Application Library: Rotordynamics_Module/Tutorials/campbell_plot_comparison (Beam Rotor vs Solid Rotor vs Solid Rotor, Fixed Frame)

model.component("comp1").physics("rotbm").feature("jrb1").feature("ffd1").set("k_u", new String[]{"0", "0", "0", "0", "1e8", "0", "0", "0", "1e8"});
model.component("comp1").physics("rotbm").feature("jrb1").feature("ffd1").set("c_u", new String[]{"0", "0", "0", "0", "1e3", "0", "0", "0", "1e3"});
// Application Library: Rotordynamics_Module/Verification_Examples/coupled_rotors

